parameters.jsonBody:
={
  "messaging_product": "whatsapp",
  "to": "{{ $json.guide_whatsapp }}",
  "type": "interactive",
  "interactive": {
    "type": "button",
    "header": {
      "type": "text",
      "text": "📋 KHAKI TOURS GUIDE BRIEFING (T-2H)"
    },
    "body": {
      "text": "Hello {{ $json.guide_name }}!\n\nHere is your official briefing for today's walk:\n\n🏛️ *Tour:* {{ $json.tour_title }}\n⏰ *Departure:* {{ $json.start_time }} (Report by {{ $json.report_time }})\n📍 *Meeting Point:* {{ $json.meeting_point }}\n🗺️ *Google Maps:* {{ $json.meeting_coordinates_url }}\n\n👥 *Confirmed Guests:* {{ $json.pax_count }} Pax\n• KYC Verified: {{ $json.kyc_verified_count }}/{{ $json.pax_count }}\n• Dietary Alerts: {{ $json.dietary_notes || 'None reported' }}\n• Special Requests: {{ $json.special_requests || 'Standard pace' }}\n\n📞 *Ops Desk Backup (Priya):* +91 98200 11002\n\nTap below once you arrive on site:"
    },
    "footer": { "text": "Khaki Tours Operations Hub | Zero-Login Guide Flow" },
    "action": {
      "buttons": [
        {
          "type": "reply",
          "reply": {
            "id": "GUIDE_CHECKIN_{{ $json.departure_id }}",
            "title": "✅ Checked-in On Site"
          }
        },
        {
          "type": "reply",
          "reply": {
            "id": "GUIDE_ISSUE_{{ $json.departure_id }}",
            "title": "⚠️ Report Delay / Issue"
          }
        }
      ]
    }
  }
}
